//! The segmenting engine.
//!
//! Highlighters are applied one after another to the whole line. Before each
//! pass the current text is split into "already highlighted" runs (everything
//! from an ANSI CSI introducer up to and including the next literal reset
//! sequence) and plain runs. Only the plain runs are offered to the
//! highlighter, which is why an earlier highlighter can block a later one from
//! matching across the region it claimed.

use crate::style::RESET;

pub trait Highlighter {
    /// Highlight a plain (not yet styled) chunk of a line.
    fn apply(&self, input: &str, out: &mut String);
}

/// Index of the next CSI introducer (`ESC [`) at or after `from`.
fn find_csi(bytes: &[u8], from: usize) -> Option<usize> {
    let mut i = from;
    while i + 1 < bytes.len() {
        if bytes[i] == 0x1b && bytes[i + 1] == b'[' {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// Index just past the first literal reset sequence at or after `from`.
fn find_reset_end(text: &str, from: usize) -> Option<usize> {
    text[from..].find(RESET).map(|p| from + p + RESET.len())
}

pub fn split_and_apply(text: &str, h: &dyn Highlighter) -> String {
    let bytes = text.as_bytes();
    if find_csi(bytes, 0).is_none() {
        let mut out = String::with_capacity(text.len() + 16);
        h.apply(text, &mut out);
        return out;
    }

    let mut out = String::with_capacity(text.len() + 32);
    let mut i = 0usize;
    while i < text.len() {
        match find_csi(bytes, i) {
            Some(start) => {
                if start > i {
                    h.apply(&text[i..start], &mut out);
                }
                match find_reset_end(text, start) {
                    Some(end) => {
                        out.push_str(&text[start..end]);
                        i = end;
                    }
                    None => {
                        out.push_str(&text[start..]);
                        i = text.len();
                    }
                }
            }
            None => {
                h.apply(&text[i..], &mut out);
                i = text.len();
            }
        }
    }
    out
}

pub fn highlight_line(line: &str, highlighters: &[Box<dyn Highlighter>]) -> String {
    let mut current = line.to_string();
    for h in highlighters {
        current = split_and_apply(&current, h.as_ref());
    }
    current
}
