//! ANSI styling primitives.

pub const RESET: &str = "\x1b[0m";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    BrightBlack,
    BrightRed,
    BrightGreen,
    BrightYellow,
    BrightBlue,
    BrightMagenta,
    BrightCyan,
    BrightWhite,
    Fixed(u8),
    Rgb(u8, u8, u8),
}

impl Color {
    fn base(self) -> Option<u8> {
        Some(match self {
            Color::Black => 0,
            Color::Red => 1,
            Color::Green => 2,
            Color::Yellow => 3,
            Color::Blue => 4,
            Color::Magenta => 5,
            Color::Cyan => 6,
            Color::White => 7,
            _ => return None,
        })
    }

    fn bright_base(self) -> Option<u8> {
        Some(match self {
            Color::BrightBlack => 0,
            Color::BrightRed => 1,
            Color::BrightGreen => 2,
            Color::BrightYellow => 3,
            Color::BrightBlue => 4,
            Color::BrightMagenta => 5,
            Color::BrightCyan => 6,
            Color::BrightWhite => 7,
            _ => return None,
        })
    }

    fn write_fg(self, out: &mut Vec<String>) {
        if let Some(n) = self.base() {
            out.push((30 + n as u16).to_string());
        } else if let Some(n) = self.bright_base() {
            out.push((90 + n as u16).to_string());
        } else {
            match self {
                Color::Fixed(n) => {
                    out.push("38".into());
                    out.push("5".into());
                    out.push(n.to_string());
                }
                Color::Rgb(r, g, b) => {
                    out.push("38".into());
                    out.push("2".into());
                    out.push(r.to_string());
                    out.push(g.to_string());
                    out.push(b.to_string());
                }
                _ => {}
            }
        }
    }

    fn write_bg(self, out: &mut Vec<String>) {
        if let Some(n) = self.base() {
            out.push((40 + n as u16).to_string());
        } else if let Some(n) = self.bright_base() {
            out.push((100 + n as u16).to_string());
        } else {
            match self {
                Color::Fixed(n) => {
                    out.push("48".into());
                    out.push("5".into());
                    out.push(n.to_string());
                }
                Color::Rgb(r, g, b) => {
                    out.push("48".into());
                    out.push("2".into());
                    out.push(r.to_string());
                    out.push(g.to_string());
                    out.push(b.to_string());
                }
                _ => {}
            }
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub faint: bool,
    pub italic: bool,
    pub underline: bool,
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }

    pub fn fg(c: Color) -> Style {
        Style {
            fg: Some(c),
            ..Style::default()
        }
    }

    pub fn is_plain(&self) -> bool {
        self.fg.is_none()
            && self.bg.is_none()
            && !self.bold
            && !self.faint
            && !self.italic
            && !self.underline
    }

    /// The SGR escape sequence that turns this style on.
    pub fn prefix(&self) -> String {
        if self.is_plain() {
            return String::new();
        }
        let mut parts: Vec<String> = Vec::new();
        if self.bold {
            parts.push("1".into());
        }
        if self.faint {
            parts.push("2".into());
        }
        if self.italic {
            parts.push("3".into());
        }
        if self.underline {
            parts.push("4".into());
        }
        if let Some(bg) = self.bg {
            bg.write_bg(&mut parts);
        }
        if let Some(fg) = self.fg {
            fg.write_fg(&mut parts);
        }
        let mut s = String::from("\x1b[");
        s.push_str(&parts.join(";"));
        s.push('m');
        s
    }
}

/// A pre-rendered style: prefix + reset, cached so hot loops avoid allocation.
#[derive(Clone, Debug, Default)]
pub struct Paint {
    pub prefix: String,
    pub plain: bool,
}

impl Paint {
    pub fn from_style(s: &Style) -> Paint {
        Paint {
            prefix: s.prefix(),
            plain: s.is_plain(),
        }
    }

    /// Append `text` wrapped in this style to `out`.
    pub fn wrap(&self, text: &str, out: &mut String) {
        if self.plain {
            out.push_str(text);
        } else {
            out.push_str(&self.prefix);
            out.push_str(text);
            out.push_str(RESET);
        }
    }

    pub fn wrap_char(&self, c: char, out: &mut String) {
        if self.plain {
            out.push(c);
        } else {
            out.push_str(&self.prefix);
            out.push(c);
            out.push_str(RESET);
        }
    }
}
